blocchi.codice:
extends Area2D

signal activated
signal deactivated

@export var is_active: bool = false

var is_player_nearby: bool = false


func _ready() -> void:
	body_entered.connect(_on_body_entered)
	body_exited.connect(_on_body_exited)
	_update_visual()


func _unhandled_input(event: InputEvent) -> void:
	if event.is_action_pressed("interact") and is_player_nearby:
		toggle()


func toggle() -> void:
	is_active = not is_active
	_update_visual()
	if is_active:
		activated.emit()
	else:
		deactivated.emit()


func _update_visual() -> void:
	if is_active:
		modulate = Color(0.4, 1.0, 0.4)
	else:
		modulate = Color(1.0, 0.4, 0.4)


func _on_body_entered(body: Node2D) -> void:
	if body.name == "Player":
		is_player_nearby = true


func _on_body_exited(body: Node2D) -> void:
	if body.name == "Player":
		is_player_nearby = false

# Misurazione del tempo di esecuzione di un algoritmo in microsecondi
var start_time: int = Time.get_ticks_usec()

# Blocco di codice da analizzare (es. aggiornamento di 500 nemici)
for i in range(500):
	var dummy_distance: float = global_position.distance_to(Vector2(i, i))

var elapsed_time: int = Time.get_ticks_usec() - start_time
print("Tempo impiegato: %d microsecondi (%.3f ms)" % [elapsed_time, elapsed_time / 1000.0])
